import React, { useEffect, useMemo, useRef, useState } from 'react';
import { openingsAPI } from '../services/api';
import ImageWithFallback from './ImageWithFallback';
import './CaseOpeningAnimation.css';

const SLOT_WIDTH = 164;
const WINNER_INDEX = 44;
const TOTAL_SLOTS = 70;
const ANIMATION_MS = 6800;

const money = (value) => `${Number(value || 0).toLocaleString('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} €`;

const normalizeImage = (url) => {
  if (!url) return '';
  const value = String(url).trim();
  if (/^https?:\/\//i.test(value) || value.startsWith('data:')) return value;
  return `/${value.replace(/^\/+/, '')}`;
};

const CaseOpeningAnimation = ({ caseId, onComplete, onClose }) => {
  const [caseData, setCaseData] = useState(null);
  const [openingResult, setOpeningResult] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [phase, setPhase] = useState('loading');
  const [openingStarted, setOpeningStarted] = useState(false);
  const [translateX, setTranslateX] = useState(0);
  const viewportRef = useRef(null);
  const openingPromiseRef = useRef(null);
  const openingPromiseCaseRef = useRef(null);
  const completedRef = useRef(false);
  const onCompleteRef = useRef(onComplete);

  useEffect(() => { onCompleteRef.current = onComplete; }, [onComplete]);

  useEffect(() => {
    if (!caseId) return undefined;

    // React 18 StrictMode mounts effects twice in development. The previous guard
    // marked the case as started before the first effect was cleaned up, so the
    // second effect returned immediately and the UI stayed forever on loading.
    // Keep one shared promise per case instead: both StrictMode passes subscribe
    // to the same POST, while the backend is charged exactly once.
    let cancelled = false;

    setLoading(true);
    setError('');
    setPhase('loading');
    setOpeningResult(null);
    setCaseData(null);
    setTranslateX(0);
    setOpeningStarted(false);
    completedRef.current = false;

    if (openingPromiseCaseRef.current !== caseId) {
      openingPromiseCaseRef.current = caseId;
      openingPromiseRef.current = openingsAPI.openCase(caseId);
    }

    const load = async () => {
      try {
        const response = await openingPromiseRef.current;
        if (cancelled) return;

        const result = response.data;
        if (!result?.item) {
          throw new Error('Le serveur n’a pas renvoyé le drop gagnant.');
        }

        const item = {
          ...result.item,
          image_url: normalizeImage(result.item.image_url),
        };

        const fallbackCase = {
          id: result.case_id,
          name: result.case_name || `Case #${result.case_id}`,
          price: Number(result.case_price || 0),
          image_url: normalizeImage(result.case_image_url),
          items: [],
        };

        setCaseData(fallbackCase);
        setOpeningResult({ ...result, item });
        setLoading(false);
        setOpeningStarted(true);
        window.setTimeout(() => {
          if (!cancelled) setPhase('rolling');
        }, 80);
      } catch (err) {
        // A shared rejected promise must be cleared so the next deliberate
        // opening can retry instead of reusing the failed request forever.
        if (openingPromiseCaseRef.current === caseId) {
          openingPromiseRef.current = null;
          openingPromiseCaseRef.current = null;
        }
        if (!cancelled) {
          const detail = err.response?.data?.detail;
          setError(detail || err.message || 'Impossible d’ouvrir cette caisse.');
          setLoading(false);
          setPhase('error');
        }
      }
    };

    load();
    return () => { cancelled = true; };
  }, [caseId]);

  const wonItem = openingResult?.item || null;

  // The backend result is enough to render a roulette even if the case catalogue
  // endpoint is unavailable. Once the opening succeeds, the animation can never
  // depend on another network request.
  const sequence = useMemo(() => {
    if (!wonItem) return [];
    return Array.from({ length: TOTAL_SLOTS }, (_, index) => {
      if (index === WINNER_INDEX) return wonItem;
      return wonItem;
    });
  }, [wonItem]);

  useEffect(() => {
    if (!openingStarted || phase !== 'rolling' || !sequence.length || !wonItem) return undefined;
    const viewportWidth = viewportRef.current?.clientWidth || Math.min(window.innerWidth - 36, 1180);
    const winnerCenter = WINNER_INDEX * SLOT_WIDTH + SLOT_WIDTH / 2;
    const target = Math.round((viewportWidth / 2) - winnerCenter);
    const frame = window.requestAnimationFrame(() => setTranslateX(target));
    const finishTimer = window.setTimeout(() => {
      setPhase('finished');
      if (!completedRef.current) {
        completedRef.current = true;
        onCompleteRef.current?.(wonItem);
      }
    }, ANIMATION_MS + 140);
    return () => { window.cancelAnimationFrame(frame); window.clearTimeout(finishTimer); };
  }, [openingStarted, phase, sequence, wonItem]);

  if (loading) {
    return (
      <div className="opening-animation-container opening-state">
        <div className="opening-loader" />
        <span className="opening-kicker">WELLCASE DROP</span>
        <strong>Ouverture de la caisse…</strong>
        <small>Le serveur sécurise ton résultat.</small>
      </div>
    );
  }

  if (error || !caseData || !wonItem) {
    return (
      <div className="opening-animation-container opening-state">
        <span className="opening-kicker">DROP ERROR</span>
        <h4>Ouverture indisponible</h4>
        <p>{error || 'Le résultat de l’ouverture est incomplet.'}</p>
        <button className="opening-collect-button" onClick={onClose}>FERMER</button>
      </div>
    );
  }

  const isFinished = phase === 'finished';
  const casePrice = Number(openingResult?.case_price ?? caseData.price ?? 0);
  const itemValue = Number(wonItem.virtual_value || 0);
  const netGain = Number(openingResult?.net_gain ?? (itemValue - casePrice));
  const rarityClass = (rarity) => rarity ? `rarity-${rarity.toLowerCase().replace(/\s+/g, '-')}` : 'rarity-default';

  return (
    <div className={`opening-animation-container ${phase}`}>
      <div className="opening-backdrop-orb orb-a" /><div className="opening-backdrop-orb orb-b" />
      <div className="opening-header">
        <span className="opening-kicker">WELLCASE / OPENING</span>
        <h3>{caseData.name}</h3>
        <p>La roue ralentit jusqu’au drop exact.</p>
      </div>

      <div className="opening-viewport" ref={viewportRef}>
        <div className="opening-viewport-vignette" />
        <div className="opening-pointer" aria-hidden="true"><span /></div>
        <div className="opening-track" style={{ width: `${sequence.length * SLOT_WIDTH}px`, transform: `translate3d(${translateX}px,0,0)` }}>
          {sequence.map((item, index) => (
            <div className="opening-slide-item" key={`${item.id}-${index}`} style={{ width: SLOT_WIDTH }}>
              <div className="opening-item-card">
                <div className="opening-item-rarity-line" />
                <ImageWithFallback src={normalizeImage(item.image_url)} alt={item.name} className="opening-item-image" />
                <div className="item-name" title={item.name}>{item.name}</div>
                <div className={`item-rarity ${rarityClass(item.rarity)}`}>{item.rarity}</div>
                <small className="opening-item-value">{money(item.virtual_value)}</small>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="opening-telemetry"><span>RESULTAT SERVEUR</span><b>{isFinished ? 'VERROUILLÉ' : 'VERROUILLÉ · RÉVÉLATION EN COURS'}</b><span>DROP #{openingResult.id}</span></div>
      {!isFinished && <div className="opening-status"><span className="status-label">OUVERTURE EN COURS</span><strong>La roue révèle ton drop…</strong><small>Accélération → vitesse → ralentissement → arrêt.</small></div>}

      {isFinished && (
        <div className="opening-result-panel">
          <div className="opening-result-main">
            <div className="won-item-glow"><div className="won-item-rays" /><ImageWithFallback src={normalizeImage(wonItem.image_url)} alt={wonItem.name} className="won-item-image" /></div>
            <div className="won-item-copy"><span className="status-label win">DROP CONFIRMÉ</span><div className="won-item-name">{wonItem.name}</div><div className={`won-item-rarity ${rarityClass(wonItem.rarity)}`}>{wonItem.rarity}</div></div>
          </div>
          <div className="opening-earnings">
            <div><span>PRIX DE LA CAISSE</span><strong>- {money(casePrice)}</strong></div>
            <div><span>VALEUR DU DROP</span><strong>{money(itemValue)}</strong></div>
            <div className={netGain >= 0 ? 'positive' : 'negative'}><span>GAIN NET</span><strong>{netGain >= 0 ? '+' : ''}{money(netGain)}</strong></div>
          </div>
          <button className="opening-collect-button" onClick={onClose}>RÉCUPÉRER LE SKIN</button>
        </div>
      )}
    </div>
  );
};

export default CaseOpeningAnimation;
